def get_expanded_rosetta():
    """Return all expanded handcrafted entries."""
    entries = []
    idx = 10000  # offset to avoid ID collision
    for concept, lang_codes in EXPANDED.items():
        cn = concept.replace('_', ' ').title()
        for lang, code in lang_codes.items():
            idx += 1
            entries.append({
                "id": f"rosetta_exp_{idx}",
                "concept": concept,
                "concept_name": cn,
                "language": lang,
                "code": code,
                "category": "rosetta_stone",
                "has_code": True,
                "code_lines": len(code.split('\n')),
                "source": "handcrafted",
            })
    return entries
